import React, { useState, useEffect } from 'react';
//import axios from 'axios';
import { generateCondition } from './ConditionGenerator';
import LineSelector from '../controls/LineSelector';
import MultiSelector from '../controls/MultiSelector';

// 1. 수직 계층 구조 (상하 관계)
const VERTICAL_ORDER = ['line', 'process', 'partid', 'equip', 'lottype', 'step'];
// 2. 최하위 동일 레벨 (형제 관계)
const Y_ITEMS = ['y1item', 'y2item'];

const SearchMonitoring = ({ dataType, onRun }) => {
  // 차트 설정 상태 추가
  const [chartConfig, setChartConfig] = useState({
    engine: 'eChart',
    type: 'scatter',
    cols: 4,
  });

  const [options, setOptions] = useState({
    lineList: [],
    processList: [],
    partidList: [],
    equipList: [],
    lottypeList: [],
    stepList: [],
    y1itemList: [],
    y2itemList: [],
  });
  const [filterInput, setFilterInput] = useState({
    line: '',
    process: '',
    partid: '',
    equip: '',
    lottype: '',
    step: '',
    y1item: '',
    y2item: '',
  });
  const [searchParams, setSearchParams] = useState({
    date: [],
    line: [],
    process: [],
    partid: [],
    equip: [],
    lottype: [],
    step: [],
    y1item: [],
    y2item: [],
  });

  const buttonStyle = {
    width: '100px', // 요청하신 200px 사이즈
    padding: '12px 0',
    backgroundColor: '#007bff',
    color: '#fff',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 'bold',
    textAlign: 'center',
    whiteSpace: 'nowrap', // 텍스트가 버튼 밖으로 나가지 않게 함
  };

  // Top Selector Layout
  const topHeight = '250px';
  const lineHeight = '219px';
  const bottomHeight = '200px';

  //선택된 카테고리의 다음 순서부터 모든 하위 항목을 초기화합니다.
  const clearLowerSelectors = (currentCategory) => {
    const currentIndex = VERTICAL_ORDER.indexOf(currentCategory);
    let targetsToClear = [];

    // Case 1: 상위 수직 계층(line~step)이 변경된 경우
    if (currentIndex !== -1) {
      // 1-1. 자신보다 아래에 있는 수직 항목들 추출
      targetsToClear = VERTICAL_ORDER.slice(currentIndex + 1);
      // 1-2. 최하위 동일 레벨인 Y Item들은 무조건 포함
      targetsToClear = [...targetsToClear, ...Y_ITEMS];
    }
    // Case 2: 최하위 레벨(y1item, y2item) 자체가 변경된 경우
    else if (Y_ITEMS.includes(currentCategory)) {
      // 최하위이므로 자기들끼리는 서로 영향을 주지 않음 (빈 배열 유지)
      targetsToClear = [];
    }

    if (targetsToClear.length === 0) return;

    // --- 실제 상태 초기화 실행 ---
    setOptions((prev) => {
      const newOptions = { ...prev };
      targetsToClear.forEach((cat) => {
        newOptions[`${cat}List`] = [];
      });
      return newOptions;
    });

    setSearchParams((prev) => {
      const newParams = { ...prev };
      targetsToClear.forEach((cat) => {
        newParams[cat] = [];
      });
      return newParams;
    });

    setFilterInput((prev) => {
      const newFilter = { ...prev };
      targetsToClear.forEach((cat) => {
        newFilter[cat] = '';
      });
      return newFilter;
    });
  };

  // 1. 필터 입력값 업데이트
  const handleFilterChange = (category, value) => {
    setFilterInput((prev) => ({ ...prev, [category]: value }));
  };

  // 2. 서버에서 데이터 조회 (Spring API)
  const fetchOptions = async (category) => {
    try {
      // 상위 항목 조회 시 하위 단계 모두 초기화
      clearLowerSelectors(category);
      const keyword = filterInput[category];
      // API 호출 주석 처리
      /*
      const res = await axios.get(`http://localhost:8080/map/options`, {
        params: { type: category, keyword: keyword },
      });
      const data = res.data;
      */

      // ConditionGenerator 활용
      const data = generateCondition(category, keyword);

      const targetList = category + 'List';
      setOptions((prev) => ({ ...prev, [targetList]: data }));
    } catch (err) {
      console.error('데이터 로드 실패:', err);
    }
  };

  // 3. 멀티 셀렉트 변경 핸들러 (기존 로직 유지)
  const handleMultiChange = (e) => {
    const { name, options } = e.target;
    clearLowerSelectors(name);
    const selectedValues = [];
    for (let i = 0; i < options.length; i++) {
      if (options[i].selected) selectedValues.push(options[i].value);
    }
    // 컴포넌트 name 속성에 따라 processes 또는 equips 배열 업데이트
    setSearchParams((prev) => ({ ...prev, [name]: selectedValues }));
  };

  // 4. Date Change
  const handleDateChange = (value) => {
    console.log('최종 선택된 D-Day 범위:', value);
    setSearchParams((prev) => ({ ...prev, date: value }));
  };
  // 차트 설정 변경 핸들러
  const handleChartConfigChange = (e) => {
    const { name, value } = e.target;
    setChartConfig((prev) => ({
      ...prev,
      [name]: name === 'cols' ? Number(value) : value, // cols는 숫자로 변환
    }));
  };

  const handleRunClick = () => {
    if (onRun && typeof onRun === 'function') {
      // 검색 조건과 차트 설정을 합쳐서 부모에게 전달
      onRun({
        ...searchParams,
        chartEngine: chartConfig.engine,
        chartType: chartConfig.type,
        chartCols: chartConfig.cols, // 부모에게 넘길 인자 추가
      });
    }
  };

  // 콤보박스 스타일
  const selectStyle = {
    padding: '5px',
    borderRadius: '4px',
    border: '1px solid #ddd',
    fontSize: '13px',
    height: '35px',
    marginRight: '10px',
    minWidth: '100px',
  };

  const labelStyle = {
    fontSize: '12px',
    fontWeight: 'bold',
    marginRight: '5px',
    color: '#555',
  };

  return (
    <div
      style={{
        paddingLeft: '15px',
        paddingRight: '15px',
        paddingTop: '10px',
        border: '1px solid #ddd',
        borderRadius: '8px',
      }}
    >
      <div style={{ display: 'flex', gap: '20px' }}>
        {/* 라인 선택기 */}
        <LineSelector
          label="라인"
          category="line"
          filterValue={filterInput.line}
          selectorHeight={lineHeight}
          pickerMinWidth="150px"
          onFilterChange={handleFilterChange}
          onFetch={fetchOptions}
          options={options.lineList}
          selectedValues={searchParams.line}
          onSelectChange={handleMultiChange}
          onDateChange={handleDateChange}
        />
        {/* 공정 선택기 */}
        <MultiSelector
          label="공정"
          category="process"
          filterValue={filterInput.process}
          selectorHeight={topHeight}
          onFilterChange={handleFilterChange}
          onFetch={fetchOptions}
          options={options.processList}
          selectedValues={searchParams.process}
          onSelectChange={handleMultiChange}
        />

        {/* 제품 선택기 */}
        <MultiSelector
          label="제품"
          category="partid"
          filterValue={filterInput.partid}
          selectorHeight={topHeight}
          onFilterChange={handleFilterChange}
          onFetch={fetchOptions}
          options={options.partidList}
          selectedValues={searchParams.partid}
          onSelectChange={handleMultiChange}
        />
        {/* 설비 선택기 */}
        <MultiSelector
          label="설비"
          category="equip"
          filterValue={filterInput.equip}
          selectorHeight={topHeight}
          onFilterChange={handleFilterChange}
          onFetch={fetchOptions}
          options={options.equipList}
          selectedValues={searchParams.equip}
          onSelectChange={handleMultiChange}
        />
        {/* Lot Type 선택기 */}
        <MultiSelector
          label="Lot Type"
          category="lottype"
          filterValue={filterInput.lottype}
          lableWidth="75px"
          selectorHeight={topHeight}
          onFilterChange={handleFilterChange}
          onFetch={fetchOptions}
          options={options.lottypeList}
          selectedValues={searchParams.lottype}
          onSelectChange={handleMultiChange}
        />
      </div>

      <div style={{ display: 'flex', marginTop: '10px', gap: '20px' }}>
        {/* STEP 선택기 */}
        <MultiSelector
          label="STEP"
          category="step"
          filterValue={filterInput.step}
          selectorHeight={bottomHeight}
          onFilterChange={handleFilterChange}
          onFetch={fetchOptions}
          options={options.stepList}
          selectedValues={searchParams.step}
          onSelectChange={handleMultiChange}
        />

        {/* Y1 ITEM 선택기 */}
        <MultiSelector
          label="Y1 ITEM"
          category="y1item"
          filterValue={filterInput.y1item}
          selectorHeight={bottomHeight}
          lableWidth="70px"
          onFilterChange={handleFilterChange}
          onFetch={fetchOptions}
          options={options.y1itemList}
          selectedValues={searchParams.y1item}
          onSelectChange={handleMultiChange}
        />

        {/* Y2 ITEM 선택기 */}
        <MultiSelector
          label="Y2 Item"
          category="y2item"
          filterValue={filterInput.y2item}
          selectorHeight={bottomHeight}
          lableWidth="70px"
          onFilterChange={handleFilterChange}
          onFetch={fetchOptions}
          options={options.y2itemList}
          selectedValues={searchParams.y2item}
          onSelectChange={handleMultiChange}
        />
      </div>
      <div
        style={{
          display: 'flex',
          justifyContent: 'flex-end', // 모든 요소를 우측으로 밀기
          alignItems: 'center',
          gap: '10px', // 버튼 사이 간격
          marginTop: '20px',
          width: '100%',
        }}
      >
        {/* Chart Engine 선택 */}
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <label style={labelStyle}>Engine</label>
          <select
            name="engine"
            value={chartConfig.engine}
            onChange={handleChartConfigChange}
            style={selectStyle}
          >
            <option value="eChart">eChart</option>
            <option value="Rechart">Rechart</option>
            <option value="Chartjs">Chartjs</option>
          </select>
        </div>
        {/* Chart Type 선택 */}
        <div style={{ display: 'flex', alignItems: 'center', marginRight: '20px' }}>
          <label style={labelStyle}>Type</label>
          <select
            name="type"
            value={chartConfig.type}
            onChange={handleChartConfigChange}
            style={selectStyle}
          >
            <option value="scatter">scatter</option>
            <option value="line">line</option>
            <option value="box">box</option>
            <option value="bar">bar</option>
          </select>
        </div>
        {/* [신규] Cols 선택 콤보박스 */}
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <label style={labelStyle}>Cols</label>
          <select
            name="cols"
            value={chartConfig.cols}
            onChange={handleChartConfigChange}
            style={{ ...selectStyle, minWidth: '60px' }}
          >
            {[...Array(10)].map((_, i) => (
              <option key={i + 1} value={i + 1}>
                {i + 1}
              </option>
            ))}
          </select>
        </div>
        {/* 각 버튼의 너비를 200px로 고정하고 수평 배치 */}
        <button
          style={{ ...buttonStyle, paddingTop: '10px', height: '35px' }}
          onClick={() => console.log('실행1')}
        >
          Add
        </button>
        <button
          style={{ ...buttonStyle, paddingTop: '10px', height: '35px' }}
          onClick={() => console.log('실행2')}
        >
          Remove
        </button>
        <button
          style={{ ...buttonStyle, paddingTop: '10px', height: '35px' }}
          onClick={() => console.log('실행3')}
        >
          Save
        </button>
        {/* Run 버튼 클릭 시 부모에게 searchParams 전달 */}
        <button
          style={{ ...buttonStyle, paddingTop: '10px', height: '35px', backgroundColor: '#28a745' }} // 실행 버튼 강조
          onClick={handleRunClick}
        >
          Run
        </button>{' '}
      </div>
    </div>
  );
};

export default SearchMonitoring;
