const HeaderMenu = ({ onMenuType, onDataType }) => {
  return (
    <header
      style={{
        padding: '10px 20px',
        background: '#2c3e50',
        color: 'white',
        display: 'flex',
        gap: '20px',
        alignItems: 'center',
      }}
    >
      <label>
        Data Type:{' '}
        <select name="dataType" onChange={(e) => onDataType(e.target.value)}>
          <option value="Gen">Gen</option>
          <option value="Api">Api</option>
        </select>
      </label>
      <button onClick={() => onMenuType('Monitoring')} style={{ cursor: 'pointer' }}>
        Device Solution Monitoring
      </button>
      <button onClick={() => onMenuType('Map')} style={{ cursor: 'pointer' }}>
        Device Solution Map
      </button>
      <button onClick={() => onMenuType('Analysis')} style={{ cursor: 'pointer' }}>
        Information
      </button>
    </header>
  );
};

export default HeaderMenu;
