import { useEffect, useMemo, useRef, useState } from "react";
import { generateGradient } from "./DieGenerator";

const WaferMap = ({ key, params, waferDatas, onUpdate, isDetail }) => {
  const canvasRef = useRef(null);
  const [dies, setEDS] = useState([]);
  const [measures, setMEASURE] = useState([]);
  const [defects, setDefects] = useState([]);
  const [cds, setMETRO] = useState([]);
  const [hoveredEDS, setHoveredEDS] = useState(null);
  const [hoveredMEASURE, setHoveredMEASURE] = useState(null);
  const [hoveredDefect, setHoveredDefect] = useState(null);
  const [hoveredMETRO, setHoveredMETRO] = useState(null);
  const { waferSize, waferEdge } = params;
  const CANVAS_PADDING = 1; // 캔버스 패딩 (px)

  const usableSize = params.waferPixelSize - 2 * CANVAS_PADDING; // 패딩을 제외한 실제 그리기 영역
  const center = params.waferPixelSize / 2; // 전체 캔버스 중심
  const scale = usableSize / waferSize; // 패딩을 제외한 크기 기준으로 스케일 계산

  // Color List 설정
  const stepCount = 50;
  const colors = useMemo(() => {
    return generateGradient("#e9db5e", "#2b38b3", stepCount);
  }, [stepCount]);

  const handleMouseMove = (e) => {
    setHoveredEDS(null);
    setHoveredMEASURE(null);
    setHoveredDefect(null);
    setHoveredMETRO(null);
    // 상수 정의
    const rect = canvasRef.current.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    // 역계산: 마우스 위치(픽셀)를 데이터 좌표(300,000 단위)로 변환
    const dataX = (mx - center) / scale;
    const dataY = (center - my) / scale;
    // 데이터 좌표계 상에서 거리 계산 (임계값도 scale에 맞춰 조정)
    const threshold = 5 / scale; // 화면상 5px 정도의 오차 허용
    var found = [];
    var info = "info...";
    // EDS
    if (params.mapType === "EDS") {
      found = dies.find((d) => {
        var valid = false;
        if (
          d.x <= dataX &&
          dataX <= d.x + d.width &&
          d.y <= dataY &&
          dataY <= d.y + d.height
        ) {
          info =
            "chip info => ID: " +
            d.id +
            ", BIN: " +
            d.bin +
            ", X: " +
            d.x +
            "um, Y: " +
            d.y +
            "um, Width: " +
            d.width +
            "um, Height: " +
            d.height +
            "um";
          valid = true;
        }
        return valid;
      });

      if (found) {
        setHoveredEDS({ ...found, px: e.clientX, py: e.clientY });
      } else {
        setHoveredEDS(null);
      }
    }
    // MEASURE
    if (params.mapType === "MEASURE") {
      found = measures.find((d) => {
        var valid = false;
        if (
          d.x <= dataX &&
          dataX <= d.x + d.width &&
          d.y <= dataY &&
          dataY <= d.y + d.height
        ) {
          valid = true;
          info =
            "chip info => ID: " +
            d.id +
            ", ItemVaue: " +
            d.itemValue.toFixed(2) +
            ", X: " +
            d.x +
            "um, Y: " +
            d.y +
            "um, Width: " +
            d.width +
            "um, Height: " +
            d.height +
            "um";
        }
        return valid;
      });

      if (found) {
        setHoveredMEASURE({ ...found, px: e.clientX, py: e.clientY });
      } else {
        setHoveredMEASURE(null);
      }
    }
    // Defect
    if (params.mapType === "DEFECT") {
      found = defects.find((d) => {
        var valid = false;
        var dist = Math.sqrt((d.x - dataX) ** 2 + (d.y - dataY) ** 2);
        if (dist < threshold) {
          valid = true;
          info =
            "defect info => ID: " +
            d.id +
            ", Type: " +
            d.type +
            ", X: " +
            d.x.toFixed(2) +
            "um, Y: " +
            d.y.toFixed(2) +
            "um, Size: " +
            d.size.toFixed(2) +
            "um";
        }
        return valid;
      });

      if (found) {
        setHoveredDefect({ ...found, px: e.clientX, py: e.clientY });
      } else {
        setHoveredDefect(null);
      }
    }
    // METRO-CD
    if (params.mapType === "METRO-CD") {
      found = cds.find((d) => {
        var valid = false;
        var dist = Math.sqrt((d.x - dataX) ** 2 + (d.y - dataY) ** 2);
        if (dist < threshold) {
          valid = true;
          info =
            "cd info => ID: " +
            d.id +
            ", X: " +
            d.x.toFixed(2) +
            "um, Y: " +
            d.y.toFixed(2) +
            "um, Value: " +
            d.cdvalue.toFixed(2);
        }
        return valid;
      });

      if (found) {
        setHoveredMETRO({ ...found, px: e.clientX, py: e.clientY });
      } else {
        setHoveredMETRO(null);
      }
    }
    onUpdate(info);
  };

  useEffect(() => {
    if (params.mapType === "EDS") {
      setEDS(waferDatas.dieList);
    } else if (params.mapType === "MEASURE") {
      setMEASURE(waferDatas.dieList);
    } else if (params.mapType === "DEFECT") {
      setDefects(waferDatas.dataList);
    } else if (params.mapType === "METRO-CD") {
      setMETRO(waferDatas.dataList);
    }

    var minvalue = 0;
    var stepvalue = 0;
    if (params.mapType === "MEASURE" || params.mapType === "METRO-CD") {
      minvalue = waferDatas.min;
      var maxvalue = waferDatas.max;
      stepvalue = (maxvalue - minvalue) / stepCount;
    }

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    // 캔버스 해상도 최적화 (Retina 대응)
    const dpr = window.devicePixelRatio || 1;
    canvas.width = params.waferPixelSize * dpr;
    canvas.height = params.waferPixelSize * dpr;
    ctx.scale(dpr, dpr);

    // 캔버스 초기화
    ctx.clearRect(0, 0, params.waferPixelSize, params.waferPixelSize);
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, params.waferPixelSize, params.waferPixelSize);

    ctx.save();
    // 좌표계 변환
    ctx.translate(center, center);
    ctx.scale(scale, -scale); // 사사분면 반전

    // 1. 웨이퍼 외곽 (Circle)
    ctx.beginPath();
    ctx.arc(0, 0, waferSize / 2, 0, Math.PI * 2);
    ctx.strokeStyle = "#333";
    ctx.lineWidth = 1 / scale;
    ctx.stroke();

    // 2-1. notch Darw
    const notchsize = params.waferSize * 0.015;
    ctx.beginPath();
    ctx.clearRect(
      -notchsize / 2.0,
      -params.waferSize / 2 - 3000,
      notchsize,
      notchsize,
    );
    ctx.stroke();
    ctx.moveTo(-notchsize / 2.0, -params.waferSize / 2);
    ctx.lineTo(0, -params.waferSize / 2 + notchsize);
    ctx.moveTo(notchsize / 2, -params.waferSize / 2);
    ctx.lineTo(0, -params.waferSize / 2 + notchsize);
    ctx.stroke();

    // 2. 유효 영역 (Edge Exclusion 반영)
    ctx.beginPath();
    ctx.arc(0, 0, waferSize / 2 - waferEdge, 0, Math.PI * 2);
    ctx.strokeStyle = "rgba(255, 0, 0, 0.3)";
    ctx.stroke();

    // 3. 샘플 Die (격자) 그리기 - DieGenerator로 생성된 dies 사용
    ctx.strokeStyle = "#d9d9e4";

    waferDatas.dieList.forEach((die) => {
      if (params.mapType === "EDS") {
        if (die.status === "Good") {
          ctx.fillStyle = "#392abe";
        } else {
          ctx.fillStyle = "#e02f38";
        }
        ctx.fillRect(die.x, die.y, die.width, die.height);
      } else if (params.mapType === "MEASURE") {
        // MEASURE Map Chip Value별 Color 설정 기능
        var idx = Math.floor((die.itemValue - minvalue) / stepvalue);
        ctx.fillStyle = colors[idx >= stepCount ? stepCount - 1 : idx];
        ctx.fillRect(die.x, die.y, die.width, die.height);
      } else if (params.mapType === "DEFECT" || params.mapType === "METRO-CD") {
        //ctx.lineWidth = 1;
        ctx.strokeRect(die.x, die.y, die.width, die.height);
      }
      // dieSize도 데이터 단위 그대로 사용
    });

    // 4. DEFECT Map 인 경우 Defect Draw
    if (params.mapType === "DEFECT") {
      waferDatas.dataList.forEach((defect) => {
        ctx.fillStyle = defect.color;
        ctx.beginPath();
        // Defect 크기를 데이터 단위로 받지만, 화면에선 일정 픽셀 크기로 보이도록 조정
        // 이 예제에서는 2픽셀 반경으로 고정 (scaleFactor 역변환)
        var renderRadius = 2 / scale;
        if (params.realSize === true) renderRadius = defect.size / 2;
        ctx.arc(defect.x, defect.y, renderRadius, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    // 4. Metro-CD Map 인 경우 Metro CD Draw
    if (params.mapType === "METRO-CD") {
      waferDatas.dataList.forEach((cd) => {
        var idx = Math.floor((cd.cdvalue - minvalue) / stepvalue);
        ctx.fillStyle = colors[idx >= stepCount ? stepCount - 1 : idx];
        ctx.beginPath();
        // Defect 크기를 데이터 단위로 받지만, 화면에선 일정 픽셀 크기로 보이도록 조정
        // 이 예제에서는 2픽셀 반경으로 고정 (scaleFactor 역변환)
        var renderRadius = 3 / scale;
        ctx.arc(cd.x, cd.y, renderRadius, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    ctx.restore();
  }, [key, params, waferDatas, isDetail]);

  return (
    <>
      <canvas
        ref={canvasRef}
        width={params.waferPixelSize}
        height={params.waferPixelSize}
        onMouseMove={handleMouseMove}
        onMouseLeave={() => setHoveredDefect(null)}
        style={{
          background: "#ffffff",
          padding: `${CANVAS_PADDING}px`,
          boxSizing: "border-box",
        }}
      />
      {hoveredEDS && (
        <div
          style={{
            position: "fixed",
            left: hoveredEDS.px + 15,
            top: hoveredEDS.py + 15,
            backgroundColor: "#1a1a1a",
            color: "#00ff00", // 터미널 느낌의 가독성
            padding: "8px",
            borderRadius: "2px",
            fontSize: "11px",
            pointerEvents: "none",
            boxShadow: "4px 4px 0px rgba(0,0,0,0.2)",
            fontFamily: "monospace",
            textAlign: "left",
          }}
        >
          <div>[EDS INFO]</div>
          <hr style={{ borderColor: "#333" }} />
          ID: {hoveredEDS.id}
          <br />
          X: {hoveredEDS.x.toFixed(0)} um
          <br />
          Y: {hoveredEDS.y.toFixed(0)} um
          <br />
          BIN: {hoveredEDS.bin}
        </div>
      )}
      {hoveredMEASURE && (
        <div
          style={{
            position: "fixed",
            left: hoveredMEASURE.px + 15,
            top: hoveredMEASURE.py + 15,
            backgroundColor: "#1a1a1a",
            color: "#00ff00", // 터미널 느낌의 가독성
            padding: "8px",
            borderRadius: "2px",
            fontSize: "11px",
            pointerEvents: "none",
            boxShadow: "4px 4px 0px rgba(0,0,0,0.2)",
            fontFamily: "monospace",
            textAlign: "left",
          }}
        >
          <div>[MEASURE INFO]</div>
          <hr style={{ borderColor: "#333" }} />
          ID: {hoveredMEASURE.id}
          <br />
          X: {hoveredMEASURE.x.toFixed(0)} um
          <br />
          Y: {hoveredMEASURE.y.toFixed(0)} um
          <br />
          VALUE: {hoveredMEASURE.itemValue.toFixed(0)}
        </div>
      )}
      {hoveredDefect && (
        <div
          style={{
            position: "fixed",
            left: hoveredDefect.px + 15,
            top: hoveredDefect.py + 15,
            backgroundColor: "#1a1a1a",
            color: "#00ff00", // 터미널 느낌의 가독성
            padding: "8px",
            borderRadius: "2px",
            fontSize: "11px",
            pointerEvents: "none",
            boxShadow: "4px 4px 0px rgba(0,0,0,0.2)",
            fontFamily: "monospace",
            textAlign: "left",
          }}
        >
          <div>[DEFECT INFO]</div>
          <hr style={{ borderColor: "#333" }} />
          ID: {hoveredDefect.id}
          <br />
          X: {hoveredDefect.x.toFixed(0)} um
          <br />
          Y: {hoveredDefect.y.toFixed(0)} um
          <br />
          TYPE: {hoveredDefect.type}
          <br />
          SIZE: {hoveredDefect.size.toFixed(0)} um
        </div>
      )}
      {hoveredMETRO && (
        <div
          style={{
            position: "fixed",
            left: hoveredMETRO.px + 15,
            top: hoveredMETRO.py + 15,
            backgroundColor: "#1a1a1a",
            color: "#00ff00", // 터미널 느낌의 가독성
            padding: "8px",
            borderRadius: "2px",
            fontSize: "11px",
            pointerEvents: "none",
            boxShadow: "4px 4px 0px rgba(0,0,0,0.2)",
            fontFamily: "monospace",
            textAlign: "left",
          }}
        >
          <div>[METRO-CD INFO]</div>
          <hr style={{ borderColor: "#333" }} />
          ID: {hoveredMETRO.id}
          <br />
          X: {hoveredMETRO.x.toFixed(0)} um
          <br />
          Y: {hoveredMETRO.y.toFixed(0)} um
          <br />
          VALUE: {hoveredMETRO.cdvalue.toFixed(0)}
        </div>
      )}
    </>
  );
};

export default WaferMap;
