import React, { useState } from 'react';
import SearchMonitoring from './Search-Monitoring'; // 검색 조건 컴포넌트
import GalleryChart from './GalleryChart';
import Output from './Output';
import { generateDatas } from './DataGenerator';

const LayoutMonitoring = () => {
  const [data, setData] = useState([]);
  const [chartType, setChartType] = useState('line');
  const [activeTab, setActiveTab] = useState('search'); // 초기 탭을 search로 설정
  const [gridCols, setGridCols] = useState(4); // 상태 추가

  // SearchMonitoring에서 Run 버튼 클릭 시 실행될 함수
  const handleRun = (selectedParams) => {
    console.log('전달받은 조회 조건:', selectedParams);

    // 로딩 표시 등을 위해 탭을 먼저 이동하거나 로딩 상태를 둘 수 있습니다.
    // setActiveTab('chart');

    // 데이터 생성 로직 (실제로는 selectedParams를 API에 던지겠지만, 여기선 더미 생성)
    const newData = generateDatas(selectedParams);

    console.log('엔진:', selectedParams.chartEngine); // eChart 등
    console.log('타입:', selectedParams.chartType); // scatter 등

    // 차트 타입 상태 업데이트
    setChartType(selectedParams.chartType);
    setGridCols(selectedParams.chartCols); // 전달받은 컬럼 수 업데이트
    setData(newData);
    setActiveTab('chart'); // 데이터 생성 후 차트 탭으로 자동 이동
  };

  return (
    <div
      style={{
        paddingTop: '1px',
        paddingLeft: '15px',
        paddingRight: '15px',
        fontFamily: 'Arial',
      }}
    >
      <h2 style={{ marginBottom: '5px' }}>Device Solution 통합 조회 시스템</h2>

      {/* 탭 메뉴 영역: Sticky 설정 */}
      <div
        style={{
          display: 'flex',
          position: 'sticky', // 스크롤 시 고정
          top: 0, // 화면 맨 위에 붙음
          backgroundColor: '#fff', // 투명 방지를 위해 배경색 필수
          zIndex: 100, // 차트나 그리드보다 위에 표시
          paddingTop: '5px',
          marginBottom: '10px',
          borderBottom: '2px solid #ddd',
        }}
      >
        <button onClick={() => setActiveTab('search')} style={tabStyle(activeTab === 'search')}>
          🔍 Search
        </button>
        <button onClick={() => setActiveTab('chart')} style={tabStyle(activeTab === 'chart')}>
          📊 Chart
        </button>
        <button onClick={() => setActiveTab('output')} style={tabStyle(activeTab === 'output')}>
          📋 Data
        </button>
      </div>

      {/* 탭 콘텐츠 영역 */}
      <div style={{ position: 'relative' }}>
        {/* Search 탭 내용 */}
        <div style={{ display: activeTab === 'search' ? 'block' : 'none' }}>
          {/* handleRun을 props로 전달 */}
          <SearchMonitoring onRun={handleRun} />{' '}
        </div>

        {/* Chart 탭 내용 */}
        <div style={{ display: activeTab === 'chart' ? 'block' : 'none' }}>
          {data.length > 0 ? (
            <GalleryChart data={data} type={chartType} cols={gridCols} />
          ) : (
            <div style={emptyStyle}>조회 데이터가 없습니다.</div>
          )}
        </div>

        {/* Data 탭 내용 */}
        <div style={{ display: activeTab === 'output' ? 'block' : 'none' }}>
          {data.length > 0 ? (
            <Output data={data} />
          ) : (
            <div style={emptyStyle}>조회 데이터가 없습니다.</div>
          )}
        </div>
      </div>
    </div>
  );
};

// 스타일 함수들
const tabStyle = (isActive) => ({
  // 기존 padding: '12px 25px' -> 수직 패딩을 5px~6px로 조정
  padding: '6px 18px',
  cursor: 'pointer',
  background: isActive ? '#007bff' : '#f8f9fa',
  color: isActive ? '#fff' : '#333',
  border: 'none',
  borderBottom: isActive ? '3px solid #0056b3' : 'none',
  // 글자 크기를 조금 줄이면 더 균형 잡혀 보입니다.
  fontSize: '13px',
  fontWeight: 'bold',
  transition: '0.3s',
  marginRight: '5px',
  borderRadius: '5px 5px 0 0',
  // 높이를 명시적으로 줄이고 싶을 때 사용 (선택 사항)
  lineHeight: '1.2',
});

const emptyStyle = {
  textAlign: 'center',
  padding: '100px',
  color: '#888',
  backgroundColor: '#f9f9f9',
  borderRadius: '10px',
};

export default LayoutMonitoring;
