// ConditionGenerator.js

export const generateCondition = (category, keyword = '') => {
  // 카테고리별 기초 데이터 소스
  const baseData = {
    line: ['Line-A', 'Line-B', 'Line-C', 'Line-D'],
    process: ['Photo', 'Etch', 'Clean', 'Diff', 'CMP', 'Ion-Imp'],
    partid: ['DRAM-8G', 'NAND-128G', 'CPU-X1', 'GPU-V2', 'MCU-S3'],
    equip: ['EQP-01', 'EQP-02', 'EQP-03', 'EQP-04', 'EQP-05'],
    lottype: ['Production', 'Test', 'Engineer', 'Rework'],
    step: ['Step-001', 'Step-005', 'Step-010', 'Step-020'],
    y1item: ['Thickness', 'Critical Dimension', 'Overlay', 'Defect Count'],
    y2item: ['Temperature', 'Pressure', 'Flow Rate', 'Humidity'],
  };

  const list = [];
  const source = baseData[category] || ['Unknown'];

  // 20개 이상의 데이터를 생성하기 위한 루프
  for (let i = 1; i <= 10; i++) {
    const baseValue = source[i % source.length];
    const item = `${baseValue}_${String(i).padStart(3, '0')}`;

    // 키워드가 있을 경우 필터링 로직 (소문자 기준)
    if (!keyword || item.toLowerCase().includes(keyword.toLowerCase())) {
      list.push(item);
    }
  }

  return list;
};
