import React, { useState, forwardRef } from 'react';
import DatePicker from 'react-datepicker';
import { differenceInDays, startOfDay } from 'date-fns';
import 'react-datepicker/dist/react-datepicker.css';

const DateSelector = ({
  onDateChange,
  pickerMinWidth = '100px',
  pickerHeight = '25px',
  pickerPadding = '0px',
  islabel = false,
}) => {
  const [fromDate, setFromDate] = useState(new Date());
  const [toDate, setToDate] = useState(new Date());

  // 날짜 객체를 숫자(예: -60)로 변환하는 핵심 함수
  const calculateDiff = (targetDate) => {
    if (!targetDate) return 0;
    const today = startOfDay(new Date());
    const target = startOfDay(targetDate);
    return differenceInDays(target, today); // 결과: -60, 0, 10 등 (Number)
  };

  // 표시용 텍스트 생성 (버튼 UI에 노출)
  const getDDayString = (val) => {
    const diff = typeof val === 'object' ? calculateDiff(val) : val;
    return diff > 0 ? `+${diff}` : `${diff}`;
  };

  // 커스텀 버튼 인풋
  const CustomInput = forwardRef(({ value, onClick }, ref) => (
    <button
      onClick={onClick}
      ref={ref}
      style={{
        width: '100%',
        height: pickerHeight,
        paddingTop: pickerPadding,
        paddingBottom: pickerPadding,
        paddingLeft: '12px',
        paddingRight: '12px',
        border: '1px solid #ddd',
        borderRadius: '4px',
        backgroundColor: '#f9f9f9',
        cursor: 'pointer',
        minWidth: pickerMinWidth,
        fontWeight: 'bold',
      }}
    >
      {/* DatePicker 내부 value를 다시 날짜로 바꿔 계산 */}
      {getDDayString(new Date(value))} ▾
    </button>
  ));

  // 날짜 변경 시 -60 형태의 숫자값들을 부모에게 반환
  const handleFromChange = (date) => {
    setFromDate(date);
    onDateChange({
      from: calculateDiff(date), // 예: -60
      to: calculateDiff(toDate), // 예: 0
    });
  };

  const handleToChange = (date) => {
    setToDate(date);
    onDateChange({
      from: calculateDiff(fromDate),
      to: calculateDiff(date),
    });
  };

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: '5px', fontFamily: 'sans-serif' }}>
      {islabel && <span style={{ fontSize: '12px', color: '#666' }}>From:</span>}
      <DatePicker
        selected={fromDate}
        onChange={handleFromChange}
        customInput={<CustomInput />}
        dateFormat="yyyy-MM-dd"
      />

      <span style={{ color: '#ccc' }}>~</span>

      {islabel && <span style={{ fontSize: '12px', color: '#666' }}>To:</span>}
      <DatePicker
        selected={toDate}
        onChange={handleToChange}
        customInput={<CustomInput />}
        dateFormat="yyyy-MM-dd"
        minDate={fromDate}
      />
    </div>
  );
};

export default DateSelector;
